statement.sql:
set nocount on; declare @PollerIdentifier uniqueidentifier set @PollerIdentifier=newid()
update wfEngine_Processing_Queue
@PollerIdentifier
where Being_Processed_Flag is NULL and Start_Processing_time <= current_timestamp; set nocount off;
select distinct i.WORK_ITEM_ID as WORK_ITEM_ID, cast(q.wf_Processing_Queue_Id as varchar(36)) wf_Processing_Queue_Id, isnull(cast(q.root_process_instance_id as varchar(36)),'') root_process_instance_id, isnull(cast(q.process_instance_id as varchar(36)),'') process_instance_id, isnull(cast(q.activity_instance_id as varchar(36)),'') activity_instance_id, ISNULL(q.Being_Processed_Flag,0) Being_Processed_Flag from FACT_WORK_ITEM i inner join wfEngine_Processing_Queue q on i.PROCESS_INSTANCE_ID=q.process_instance_id and i.ACTIVITY_INSTANCE_ID=q.activity_instance_id
q.Processing_Engine_id=@PollerIdentifier and q.Being_Processed_Flag is NULL and q.Start_Processing_time <= current_timestamp
